<?php require_once __DIR__.'/../includes/config.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$s=$pdo->prepare('SELECT * FROM admins WHERE username=?');$s->execute([trim($_POST['username']??'')]);$a=$s->fetch();if($a&&password_verify($_POST['password']??'',$a['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=$a['id'];$_SESSION['admin_name']=$a['username'];header('Location: dashboard.php');exit;}$error='Invalid administrator credentials.';}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin login | Ladle Loan</title><link rel="stylesheet" href="../assets/style.css"></head><body><div class="form-wrap"><form class="form-card" method="post"><a href="../index.php">Ladle Loan</a><h1>Administrator login</h1><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Username<input name="username" required></label><label>Password<input type="password" name="password" required></label><button class="btn">Login</button><p><a href="setup.php">First-time admin setup</a></p></form></div></body></html>